export type GitHubErrorKind =
  | 'invalid-input'
  | 'not-found'
  | 'rate-limited'
  | 'network'
  | 'timeout'
  | 'http'
  | 'invalid-response'
  | 'wrong-target-kind';

export interface GitHubErrorOptions {
  status?: number;
  retryAfterSeconds?: number;
  rateLimitResetAt?: string;
}

/**
 * A safe, typed GitHub client failure. Messages are generated by this
 * extension; raw response bodies and request details are never included.
 */
export class GitHubClientError extends Error {
  readonly kind: GitHubErrorKind;
  readonly status: number | undefined;
  readonly retryAfterSeconds: number | undefined;
  readonly rateLimitResetAt: string | undefined;

  constructor(kind: GitHubErrorKind, message: string, options: GitHubErrorOptions = {}) {
    super(message);
    this.name = 'GitHubClientError';
    this.kind = kind;
    this.status = options.status;
    this.retryAfterSeconds = options.retryAfterSeconds;
    this.rateLimitResetAt = options.rateLimitResetAt;
  }
}

export function isGitHubClientError(value: unknown): value is GitHubClientError {
  return value instanceof GitHubClientError;
}
